 "content": "def transform(grid):
    """Color centers of solid 3x3 patches, using the nearest colored seed."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 1)]

    # A seed is itself part of the foreground pattern. A center is eligible
    # when the full 3x3 neighborhood is foreground (1 or a colored seed).
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(grid[rr][cc] != 0
                   for rr in range(r - 1, r + 2)
                   for cc in range(c - 1, c + 2)):
                if seeds:
                    _, _, color = min(seeds, key=lambda s: abs(r-s[0]) + abs(c-s[1]))
                    if grid[r][c] == 1:
                        out[r][c] = color
    return out
