    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 1 for rr in (r, r+1) for cc in (c, c+1)):
                # Each repeated patch takes the color of its nearest key marker.
                _, _, color = min(seeds, key=lambda s: abs((r+s[0]) - 2*s[0]) + abs((c+s[1]) - 2*s[1]))
